function dpi_snapshot():string{$hash=hash_init('sha256');foreach(['design_payment_events','design_payment_heads','design_payment_invoices','studio_invoices','invoice_payments','audit'] as $table){$count=(int)query('SELECT COUNT(*) FROM '.table($table))->fetchColumn();hash_update($hash,$table.':'.$count.';');for($offset=0;$offset<$count;$offset+=20)foreach(all('SELECT * FROM '.table($table).' ORDER BY id LIMIT 20 OFFSET '.$offset) as $row)hash_update($hash,design_payments_json($row));}return hash_final($hash);}
function dpi_issue(int $request,array $view,?string $stage=null):array{return design_payments_issue($view['project']['id'],1,dp_id($request),$view['expected'],$view['schedule']['id'],$view['fingerprint'],$stage??$view['stages'][0]['id']);}
function dpi_offer(int $job,int $request,bool $split=false):array {
    query('INSERT INTO '.table('studio_jobs').' (id,client_id,title,summary,stage,milestones,created_at,updated_at) VALUES (?,1,?,\'Agreed scope\',\'design\',\'Existing milestone\',?,?)',[$job,'Invoice project '.$job,'2025-01-01 00:00:00','2025-01-01 00:00:00']);
    query('INSERT INTO '.table('studio_versions')." (job_id,kind,version_no,title,body,preview_url,decision,feedback,decided_by,decided_at,created_at) VALUES (?,'proposal',1,'Invoice proposal','Agreed scope','','approved','',1,'2025-01-02 00:00:00','2025-01-01 00:00:00')",[$job]);
    $fields=dp_fields($request,$job);
    if($split){
        $milestone=dp_id($request+70);$plan=['scope'=>'Scope','assigned_contact'=>'Studio','target_date'=>null,'client_action'=>'','blockers'=>'','milestones'=>[['id'=>$milestone,'title'=>'Review','details'=>'','state'=>'planned','owner'=>'studio','due_date'=>null,'depends_on'=>[]]]];
        project_planning_save($job,1,dp_id($request+80),project_planning_staff_get($job)['expected'],$plan);
        $fields['stages']=[['id'=>dp_id($request+71),'kind'=>'deposit','title'=>'Agreed deposit','calculation'=>'percent','value'=>2500,'due_date'=>'2026-12-01','milestone_id'=>''],['id'=>dp_id($request+72),'kind'=>'milestone','title'=>'Design review installment','calculation'=>'fixed','value'=>3000,'due_date'=>'','milestone_id'=>$milestone],['id'=>dp_id($request+73),'kind'=>'final','title'=>'Final remainder','calculation'=>'remainder','value'=>0,'due_date'=>'','milestone_id'=>'']];
    }
    design_payments_publish($job,1,dp_id($request),dp_view($job)['expected'],$fields);return dp_view($job);
}
